      "! ADIM 3: IOS EPC (12.4(20)T+)",
      "monitor capture buffer CAP_BUF size 2048 max-size 1518 circular",
      "monitor capture point ip cef CAP_POINT GigabitEthernet0/0 both",
      "monitor capture point associate CAP_POINT CAP_BUF",
