function copyToClipboard(text) {
  navigator.clipboard.writeText(text).then(() => {
    const t = document.getElementById("toast");
    t.textContent = "Kopyalandi: " + text.substring(0, 50) + (text.length > 50 ? "..." : "");
    t.classList.add("show");
    setTimeout(() => t.classList.remove("show"), 1800);
  });
}
function showSection(id) {
  document.querySelectorAll(".section").forEach(s => s.classList.remove("active"));
  document.querySelectorAll(".nav-list a").forEach(a => a.classList.remove("active"));
  const section = document.getElementById(id);
  if (section) section.classList.add("active");
  const nav = document.querySelector(`.nav-list a[data-section="${id}"]`);
  if (nav) nav.classList.add("active");
  localStorage.setItem("cisco-section", id);
  document.getElementById("main").scrollTo(0, 0);
}
function makeCodeCell(code) {
  return `<span class="filter-code" onclick="copyToClipboard('${code.replace(/'/g, "\\'").replace(/\n/g, "\\n")}')">${escHtml(code)}</span>`;
}
function escHtml(s) { return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function sevDot(sev) { return `<span class="sev-badge sev-${sev}"></span>`; }

function renderDashboard() {
  const cats = [...new Set(COMMANDS.map(c => c.cat))];
  const el = document.getElementById("dashboard");
  el.innerHTML = `
    <div class="hero">
      <h2>Cisco CLI Hub</h2>
      <p class="lead">IOS / NX-OS Switch &amp; Router CLI referansi. BGP, OSPF, EIGRP, STP, VLAN, HSRP, IPsec, MPLS, QoS, NAT, ACL, vPC ve daha fazlasi.<br>
      Komutlara tikla &rarr; kopyala &rarr; CLI'a yapistir.</p>
      <div class="stats-grid">
        <div class="stat-card"><div class="num">${COMMANDS.length}</div><div class="label">CLI Komut</div></div>
        <div class="stat-card"><div class="num">${cats.length}</div><div class="label">Kategori</div></div>
        <div class="stat-card"><div class="num">${SCENARIOS.length}</div><div class="label">Senaryo</div></div>
        <div class="stat-card"><div class="num">${GITHUB_RESOURCES.length + WEB_RESOURCES.length}</div><div class="label">Kaynak</div></div>
      </div>
    </div>
    <div class="content-block">
      <h3>Hizli Erisim</h3>
      <div class="card-grid">
        <div class="card" onclick="showSection('commands')" style="cursor:pointer"><h3>Komut Kutuphanesi</h3><p>Tum ${COMMANDS.length} komutu kategorilere gore filtrele.</p></div>
        <div class="card" onclick="showSection('bgp')" style="cursor:pointer"><h3>BGP</h3><p>Path selection, neighbor states, route-reflector.</p></div>
        <div class="card" onclick="showSection('ospf')" style="cursor:pointer"><h3>OSPF</h3><p>Areas, neighbor states, DR/BDR, LSA types.</p></div>
        <div class="card" onclick="showSection('vlan')" style="cursor:pointer"><h3>VLAN / STP</h3><p>VLAN, trunking, STP, portfast, bpduguard.</p></div>
        <div class="card" onclick="showSection('ipsec')" style="cursor:pointer"><h3>IPsec VPN / GRE</h3><p>ISAKMP, transform-set, crypto map, GRE tunnel.</p></div>
        <div class="card" onclick="showSection('scenarios')" style="cursor:pointer"><h3>Sorun Senaryolari</h3><p>${SCENARIOS.length} troubleshooting senaryosu.</p></div>
      </div>
    </div>
    <div class="hint-box">
      <span class="note-label">IOS vs NX-OS Farklari:</span><br>
      NX-OS'ta modulleri <code>feature &lt;modul&gt;</code> ile etkinlestirmeniz gerekir (feature ospf, feature bgp, feature vpc, feature lacp...).<br>
      IOS'ta <code>copy run start</code> = NX-OS'ta <code>copy running-config startup-config</code>.<br>
      NX-OS'ta VLAN route domain, VDC, vPC gibi ek kavramlar var.
    </div>
  `;
}

function renderGenericSection(sectionId, title, desc, categories) {
  const cmds = COMMANDS.filter(c => categories.includes(c.cat));
  const el = document.getElementById(sectionId);
  if (!el) return;

  // Check for config guides
  const guides = CONFIG_GUIDES[sectionId] || [];
  const guidesHtml = guides.length > 0 ? guides.map(g => `
    <details class="output-example">
      <summary>${escHtml(g.title)}</summary>
      <div class="output-body">
        <pre><code>${g.steps.map(s => escHtml(s)).join("\n")}</code></pre>
        ${g.note ? `<div class="hint-box" style="margin:12px 16px"><span class="note-label">Not:</span> ${escHtml(g.note)}</div>` : ""}
      </div>
    </details>
  `).join("") : "";

  el.innerHTML = `
    <div class="section-header"><h2>${title}</h2><div class="description">${desc}</div></div>
    ${guidesHtml ? `<div class="content-block"><h3>Adim Adim Yapilandirma / Hata Giderme Rehberi</h3>${guidesHtml}</div>` : ""}
    <div class="content-block">
      <h3>Tum Komutlar (${cmds.length})</h3>
      <div class="filter-list">
        ${cmds.map(c => `<div class="filter-item">${sevDot(c.sev)} ${makeCodeCell(c.code)}<span class="filter-desc">${escHtml(c.desc)}</span></div>`).join("")}
      </div>
    </div>
  `;
}

function renderCommands() {
  const cats = [...new Set(COMMANDS.map(c => c.cat))];
  const el = document.getElementById("commands");
  el.innerHTML = `
    <div class="section-header"><h2>Komut Kutuphanesi</h2><div class="description">${COMMANDS.length} komut, ${cats.length} kategoride.</div></div>
    <div class="category-tabs" id="cmd-tabs"></div>
    <input type="text" id="cmd-search" placeholder="Komut ara..." style="width:100%;background:var(--bg-2);border:1px solid var(--border);color:var(--text-0);padding:8px 10px;border-radius:6px;font-size:13px;margin-bottom:12px;outline:none;font-family:var(--mono);">
    <div id="cmd-table-wrap"></div>
  `;
  const tabsEl = document.getElementById("cmd-tabs");
  tabsEl.innerHTML = `<span class="category-tab active" data-cat="Tumu">Tumu (${COMMANDS.length})</span>` +
    cats.map(c => `<span class="category-tab" data-cat="${c}">${c} (${COMMANDS.filter(cmd => cmd.cat === c).length})</span>`).join("");
  let activeCat = "Tumu";
  function renderTable(filter) {
    let cmds = activeCat === "Tumu" ? COMMANDS : COMMANDS.filter(c => c.cat === activeCat);
    if (filter) { const f = filter.toLowerCase(); cmds = cmds.filter(c => matchesQuery(c, f)); }
    const wrap = document.getElementById("cmd-table-wrap");
    if (!cmds.length) { wrap.innerHTML = `<p class="muted">Sonuc bulunamadi.</p>`; return; }
    wrap.innerHTML = `<table class="filter-table"><thead><tr><th style="width:30px"></th><th>Komut</th><th>Aciklama</th><th>Kategori</th></tr></thead><tbody>` +
      cmds.map(c => `<tr><td>${sevDot(c.sev)}</td><td>${makeCodeCell(c.code)}</td><td class="filter-desc">${escHtml(c.desc)}</td><td class="muted" style="font-size:11px;">${escHtml(c.cat)}</td></tr>`).join("") +
      `</tbody></table>`;
  }
  tabsEl.querySelectorAll(".category-tab").forEach(tab => {
    tab.onclick = () => { tabsEl.querySelectorAll(".category-tab").forEach(t => t.classList.remove("active")); tab.classList.add("active"); activeCat = tab.dataset.cat; renderTable(document.getElementById("cmd-search").value); };
  });
  document.getElementById("cmd-search").addEventListener("input", e => renderTable(e.target.value));
  renderTable("");
}

function renderScenarios() {
  const el = document.getElementById("scenarios");
  el.innerHTML = `
    <div class="section-header"><h2>Sorun Senaryolari</h2><div class="description">${SCENARIOS.length} troubleshooting senaryosu.</div></div>
    ${SCENARIOS.map(s => `
      <div class="scenario">
        <div class="scenario-header"><span class="badge badge-${s.severity}">${s.severity === "err" ? "Kritik" : s.severity === "warn" ? "Orta" : "Bilgi"}</span><h3>${escHtml(s.title)}</h3></div>
        <div class="scenario-symptom">${escHtml(s.symptom)}</div>
        <div class="filter-list">${s.steps.map(st => `<div class="filter-item">${makeCodeCell(st.code)}<span class="filter-desc">${escHtml(st.desc)}</span></div>`).join("")}</div>
        ${s.hint ? `<div class="hint-box"><span class="note-label">Ipucu:</span> ${escHtml(s.hint)}</div>` : ""}
      </div>
    `).join("")}
  `;
}

function renderGithub() {
  const el = document.getElementById("github");
  el.innerHTML = `
    <div class="section-header"><h2>Kaynaklar</h2></div>
    <div class="content-block"><h3>GitHub Projeleri</h3><div class="card-grid">
      ${GITHUB_RESOURCES.map(r => `<div class="card"><h3>${escHtml(r.name)}</h3><p>${escHtml(r.desc)}</p><a href="${r.url}" target="_blank">${r.url}</a></div>`).join("")}
    </div></div>
    <div class="content-block"><h3>Web Kaynaklari</h3><div class="card-grid">
      ${WEB_RESOURCES.map(r => `<div class="card"><h3>${escHtml(r.name)}</h3><p>${escHtml(r.desc)}</p><a href="${r.url}" target="_blank">${r.url}</a></div>`).join("")}
    </div></div>
  `;
}

function handleSearch(query) {
  if (!query || query.length < 2) { const last = localStorage.getItem("cisco-section") || "dashboard"; showSection(last); return; }
  const q = query.toLowerCase();
  const results = COMMANDS.filter(c => matchesQuery(c, q));
  showSection("dashboard");
  const el = document.getElementById("dashboard");
  if (!results.length) { el.innerHTML = `<div class="section-header"><h2>Arama: "${escHtml(query)}"</h2><div class="description">Sonuc bulunamadi.</div></div>`; return; }
  el.innerHTML = `<div class="section-header"><h2>Arama: "${escHtml(query)}"</h2><div class="description">${results.length} sonuc.</div></div>
    <table class="filter-table"><thead><tr><th style="width:30px"></th><th>Komut</th><th>Aciklama</th><th>Kategori</th></tr></thead><tbody>
    ${results.map(c => `<tr><td>${sevDot(c.sev)}</td><td>${makeCodeCell(c.code)}</td><td class="filter-desc">${escHtml(c.desc)}</td><td class="muted" style="font-size:11px;">${escHtml(c.cat)}</td></tr>`).join("")}
    </tbody></table>`;
}

